/// MS code
/// </summary>
[ExtensionOf(classStr(GUPCodeExtensions))]
final class METGUPCodeExtensions_Extension
{
}

Method.Source:
/// <summary>
/// MS code
/// if the rule is set with OR relation, skip the original matching logic
/// the original matching logic only handle the normal rule without OR relation
/// </summary>
/// <param name = "_rebateTable">TAMRebateTable</param>
/// <returns>GUPPricingRule</returns>    
public static GUPPricingRule getHeaderRuleForRebateQuery(TAMRebateTable _rebateTable)
{
    GUPPricingRule headerRule = next getHeaderRuleForRebateQuery(_rebateTable);

    if (TAMRebateParameters::find().METUseOrAttributes)
    {
        if (GUPPricingRule::metIsOrRule(_rebateTable.PricingRuleHeader))
        {
            headerRule.clear();
        }
    }

    return headerRule;
}

/// <summary>
/// MS code
/// </summary>
/// <param name = "_rebateTable">TAMRebateTable</param>
/// <returns>GUPPricingRule</returns>
public static GUPPricingRule getLineRuleForRebateQuery(TAMRebateTable _rebateTable)
{
    GUPPricingRule lineRule = next getLineRuleForRebateQuery(_rebateTable);

    if (TAMRebateParameters::find().METUseOrAttributes)
    {        
        if (GUPPricingRule::metIsOrRule(_rebateTable.PricingRuleLine))
        {
            lineRule.clear();
        }
    }

    return lineRule;
}

/// <summary>
/// MS code
/// </summary>
/// <param name = "_ruleCondition">GUPPricingRuleCondition</param>
/// <returns>boolean</returns>
public static boolean shouldSkipRuleConditionWhenCalculateRuleHash(GUPPricingRuleCondition _ruleCondition)
{
    boolean ret = next shouldSkipRuleConditionWhenCalculateRuleHash(_ruleCondition);

    // Only AND attribute calculate rule hash at original logic, skip OR attribute
    if (TAMRebateParameters::find().METUseOrAttributes)
    {
        ret = _ruleCondition.METisOR == NoYes::Yes;
    }
    return ret;
}
